168	// expandTilde expands a leading "~" or "~/" to the user's home directory. Other
169	// forms (e.g. "~user") are left untouched — only the current user's home is
170	// resolved.
171	func expandTilde(p string) (string, error) {
172		if p != "~" && !strings.HasPrefix(p, "~/") {
173			return p, nil
174		}
175		home, err := os.UserHomeDir()
176		if err != nil {
177			return "", err
178		}
179		if p == "~" {
180			return home, nil
181		}
182		return filepath.Join(home, p[2:]), nil
183	}
