func abortRebase(path: String, projectRoot: String) async -> VCSRemoteActionResult {
  guard vcs != "jj" else {
    // jj's rebase is atomic and undoable — there is no half-finished state to abort.
    return .ok(summary: "Nothing to abort")
  }
