  let comparedTo: String
  let ahead: Int?
  let behind: Int?
  /// The counterpart ref is gone from the remote (or was never pushed). Counts are meaningless; the
  /// toolbar offers Publish rather than Push.
  let gone: Bool
  /// An unbookmarked jj `@` has diverged from `trunk()` entirely, so `behind` was not measured
  /// against it (would be meaningless) and Pull must be disabled rather than rebasing onto a base
  /// that isn't actually an ancestor. See `VCSRemoteFailure.noKnownUpstream`. Always `false` for
  /// git and for a bookmarked jj `@`, where `trunk()` never enters the comparison at all.
  let noKnownUpstream: Bool

  init(comparedTo: String, ahead: Int?, behind: Int?, gone: Bool, noKnownUpstream: Bool = false) {
    self.comparedTo = comparedTo
    self.ahead = ahead
    self.behind = behind
    self.gone = gone
    self.noKnownUpstream = noKnownUpstream
