  /// git and for a bookmarked jj `@`, where `trunk()` never enters the comparison at all.
  let noKnownUpstream: Bool

  init(comparedTo: String, ahead: Int?, behind: Int?, gone: Bool, noKnownUpstream: Bool = false) {
